import json

class CsvExporter:
    name = "csv"

    def export(self, rows):
        if not rows:
            return ""
        header = list(rows[0].keys())
        lines = [",".join(header)]
        for r in rows:
            lines.append(",".join(str(r[k]) for k in header))
        return "\n".join(lines)

class JsonExporter:
    name = "json"

    def export(self, rows):
        return json.dumps(rows)

def export_all(rows, exporters):
    return {e.name: e.export(rows) for e in exporters}
